package com.vandorlabs.neoforge;
import com.google.gson.*;
import com.vandorlabs.neoforge.programmer.*;
import com.vandorlabs.neoforge.credentials.NativeCredentialItems;
import com.vandorlabs.neoforge.inventory.NativeInventoryItems;
import java.nio.file.*;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.*;
import net.minecraft.world.item.ItemStack;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Staging only: no registered host, physical adoption, world publication or fake capability. */
@EventBusSubscriber(modid="vandorlabs")
public final class ProgrammerSavedChecks {
 private static int checks;
 private static void need(boolean valid,String why){checks++;if(!valid)throw new AssertionError("Programmer saved: "+why);}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!"programmer-saved".equals(System.getProperty("vandorlabs.transmitterPhase")))return;var server=event.getServer();try{JsonObject source;try(var reader=Files.newBufferedReader(Path.of(System.getenv("VANDOR_PROGRAMMER_SAVED_REFERENCE")))){source=JsonParser.parseReader(reader).getAsJsonObject();}need(source.get("golden").getAsString().equals("c9fab72182445314cc7f6999ac818f586df26e733ad50ebdfef59335c5a19de3"),"frozen Source save corpus");var registries=server.registryAccess();CompoundTag example=null;int cases=0;for(var value:source.getAsJsonArray("cases")){var row=value.getAsJsonObject();var raw=TagParser.parseTag(row.get("raw").getAsString());var before=raw.copy();var staged=NativeProgrammerSnapshot.prepare(raw,registries);need(staged.draft().journal()==row.get("journal").getAsBoolean()&&staged.draft().vehicle()==row.get("vehicle").getAsBoolean()&&staged.draft().title().equals(row.get("title").getAsString()),"source draft flags/title");for(int page=0;page<8;page++)need(staged.draft().pages().get(page).equals(row.getAsJsonArray("pages").get(page).getAsString()),"source page normalization");need(staged.writing()==row.get("writing").getAsInt()&&staged.complete()==row.get("complete").getAsInt()&&staged.status().name().equals(row.get("status").getAsString()),"source authoritative phase counters");for(int slot=0;slot<3;slot++){var expected=NativeInventoryItems.legacy(TagParser.parseTag(row.getAsJsonArray("items").get(slot).getAsString()),registries);var actual=staged.item(slot);var owned=NativeCredentialItems.legacyCredentialData(actual);owned.remove("Slot");need(actual.getItem()==expected.getItem()&&actual.getCount()==expected.getCount()&&NativeCredentialItems.company(actual)==NativeCredentialItems.company(expected)&&owned.equals(NativeCredentialItems.legacyCredentialData(expected)),"source inventory and complete item payload");if(!actual.isEmpty()){actual.setCount(64);need(staged.item(slot).getCount()==1,"staged items cannot be mutated through accessor");}}
  var saved=staged.original();staged.writeKnownInto(saved,registries);need(saved.getCompound("ForeignSettings").equals(raw.getCompound("ForeignSettings"))&&raw.equals(before),"unrelated settings retained/input unchanged");var round=NativeProgrammerSnapshot.prepare(saved,registries);need(round.draft().equals(staged.draft())&&round.writing()==staged.writing()&&round.complete()==staged.complete(),"native versioned saved roundtrip");for(int slot=0;slot<3;slot++)need(NativeInventoryItems.write(round.item(slot),registries).equals(NativeInventoryItems.write(staged.item(slot),registries)),"native physical slot roundtrip");if(row.get("profile").getAsInt()==1&&example==null)example=raw.copy();cases++;}
  need(cases==3528&&example!=null,"complete Source saved matrix");refusals(example,registries);System.out.println("[vandorlabs][programmer-saved] PASS sourceCases="+cases+" checks="+checks);
 }catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][programmer-saved] FAIL "+failure);}finally{server.halt(false);}}
 private static void refused(CompoundTag raw,HolderLookup.Provider registries,String name){var original=raw.copy();try{NativeProgrammerSnapshot.prepare(raw,registries);throw new AssertionError("Accepted "+name);}catch(IllegalArgumentException expected){}need(raw.equals(original),"refused original unchanged: "+name);}
 private static void refusals(CompoundTag seed,HolderLookup.Provider registries){for(int mode=0;mode<15;mode++){var raw=seed.copy();var items=raw.getList("Items",Tag.TAG_COMPOUND);switch(mode){case 0->items.add(items.getCompound(0).copy());case 1->items.getCompound(0).putByte("Slot",(byte)3);case 2->items.getCompound(0).remove("Slot");case 3->items.getCompound(0).putInt("Slot",0);case 4->items.getCompound(0).putByte("Count",(byte)2);case 5->items.getCompound(0).putShort("Damage",(short)7);case 6->{var caps=new CompoundTag();caps.putByteArray("foreign:owner",new byte[]{3,17,29});raw.put("ForgeCaps",caps);}case 7->raw.putString("ForgeCaps","malformed");case 8->raw.putBoolean("ProgrammerProjection",true);case 9->raw.put("ProgrammerPlacementRecovery",new CompoundTag());case 10->raw.putInt(NativeProgrammerSnapshot.VERSION,2);case 11->raw.putString("Items","opaque inventory");case 12->raw.putBoolean("Vehicle",true);case 13->items.getCompound(0).getCompound("tag").putString("ChipType","vehicle");case 14->raw.putString("components","unsupported");}if(mode==13){var tag=items.getCompound(0).getCompound("tag");tag.putString("ChipType","vehicle");items.getCompound(0).put("tag",tag);}refused(raw,registries,"profile "+mode);}
  var raw=seed.copy();var caps=new CompoundTag();caps.putByteArray("foreign:item",new byte[]{3,17,29});raw.getList("Items",Tag.TAG_COMPOUND).getCompound(0).put("ForgeCaps",caps);var staged=NativeProgrammerSnapshot.prepare(raw,registries);need(NativeCredentialItems.legacyCredentialData(staged.item(0)).getCompound("ForgeCaps").equals(caps),"known credential opaque capability wrapper retained");var exposed=staged.original();exposed.remove("ForeignSettings");need(staged.original().contains("ForeignSettings"),"original accessor is defensive");
 }
}
